  static String findMuscleGroup(String movementName) {
    if (movementName.trim().isEmpty) return "";
    final query = movementName.trim().toLowerCase();

    for (var entry in library.entries) {
      for (var move in entry.value) {
        if (move.toLowerCase() == query) {
          return entry.key;
        }
      }
    }

    for (var entry in library.entries) {
      for (var move in entry.value) {
        if (move.toLowerCase().contains(query) || query.contains(move.toLowerCase())) {
          return entry.key;
        }
      }
    }

    return "Genel Egzersiz";
  }

  static List<Map<String, String>> searchExercises(String query) {
    if (query.trim().isEmpty) return [];
    final q = query.trim().toLowerCase();
    final List<Map<String, String>> results = [];

    for (var entry in library.entries) {
      final category = entry.key;
      for (var move in entry.value) {
        if (move.toLowerCase().contains(q) || category.toLowerCase().contains(q)) {
          results.add({
            "category": category,
            "movement": move,
          });
        }
      }
    }
    return results;
  }
